    def imagen(self, elem):
        # Devuelve la imagen asociada a cada elemento
        # Si es bigfoot se elige según su edad
        if elem.car == '1':
            if elem.edad < Juego.EDAD_ESCOMBROS:
                return self.imgs['1a']
            elif elem.edad == Juego.EDAD_ESCOMBROS:
                return self.imgs['1b']
            else:
                return self.imgs['1c']
        else:
            return self.imgs[elem.car]        

    def evtNuevaPartida(self, event):  # wxGlade: VentPpal.<event_handler>
        self.timer.Stop()
        with MyDialog(self) as dlg:
            if dlg.ShowModal() == wx.ID_CANCEL:
                return
            tipo = dlg.rb_inicio_partida.Selection
            nfil = dlg.spin_fil.Value
            ncol = dlg.spin_col.Value
        if tipo == 0:
            with wx.FileDialog(self, "Abrir fichero", wildcard="Todos los ficheros (*.*)|*.*",
               style=wx.FD_OPEN | wx.FD_FILE_MUST_EXIST) as fileDialog:
                if fileDialog.ShowModal() == wx.ID_CANCEL:
                    return
                self.juego = Juego(fileDialog.GetPath())
        elif tipo == 1:
            self.juego = Juego()
        else:
            self.juego = Juego(nfil=nfil, ncol=ncol)
        self.fin = False
        self.btn_almacen.Enabled = True
        self.etq_estado.Label = "Pulse en el tablero para colocar las fichas"
        nfil, ncol = self.juego.nfil, self.juego.ncol
        self.tablero.SetMinSize((self.IMG_LX*ncol+1, self.IMG_LY*nfil+1))
        self.panel_1.Fit()
        self.Fit()
        self.tpo_act = VentPpal.TPO_JUG
        self.actualizar()
        self.timer.Start(VentPpal.TIMER_INTERVAL)

    def actualizar(self):
        self.dibujar(wx.ClientDC(self.tablero))
        self.img_almacen.Bitmap = self.imagen(self.juego.almacen)
        self.img_actual.Bitmap = self.imagen(self.juego.actual)
        self.etq_ptos.Label = f"{self.juego.puntos}"

    def evtDibujar(self, event):  # wxGlade: VentPpal.<event_handler>
        self.dibujar(wx.PaintDC(self.tablero))
        
    def dibujar(self, dc):
        nf, nc = self.juego.nfil, self.juego.ncol
        dc.Clear()
        dc.Pen = wx.GREY_PEN
        for i in range(nf):
            for j in range(nc):
                elem = self.juego[i,j]
                x, y = j*self.IMG_LX, i*self.IMG_LY
                dc.DrawRectangle(x, y, self.IMG_LX, self.IMG_LY)
                dc.DrawBitmap(self.imagen(elem), x, y)
                
    def evtAlmacen(self, event):  # wxGlade: VentPpal.<event_handler>
        self.juego.cambio_almacen()
        self.actualizar()

    def evtRaton(self, event):  # wxGlade: VentPpal.<event_handler>
        if self.fin:
            return
        fil = event.y // self.IMG_LY
        col = event.x // self.IMG_LX        
        if self.juego.jugada_correcta(fil, col):
            self.timer.Stop()
            self.fin = self.juego.jugar(fil, col, self.on_kill, self.on_colapso, self.on_bebes, self.on_movimiento)
            self.actualizar()
            if self.fin:
                self.etq_estado.Label = "Partida Finalizada!"
                splash = wx.adv.SplashScreen(self.img_game_over, wx.adv.SPLASH_CENTRE_ON_SCREEN | wx.adv.SPLASH_TIMEOUT,
                             4000, None, -1, wx.DefaultPosition, wx.DefaultSize,
                             wx.BORDER_SIMPLE | wx.STAY_ON_TOP)
                wx.Yield()
            else:
                self.etq_estado.Label = f"Turno: {self.juego.turno}"
                self.tpo_act = VentPpal.TPO_JUG
                self.etq_tiempo.Label = f"{self.tpo_act}"
                self.timer.Start(VentPpal.TIMER_INTERVAL)
        else:
            self.etq_estado.Label = "Jugada Errónea"
            self.etq_estado.SetForegroundColour(wx.Colour(192, 0, 0))           

    def evtTimer(self, event):        
        self.tpo_act = self.tpo_act-1
        self.etq_tiempo.Label = f"{self.tpo_act}"
        if self.tpo_act < 0:
            self.timer.Stop()
            self.snd_out_time.Play()            
            self.fin = self.juego.jugar_azar(self.on_kill, self.on_colapso, self.on_bebes, self.on_movimiento)
            self.actualizar()
            if self.fin:
                self.etq_estado.Label = "Partida Finalizada!"
                splash = wx.adv.SplashScreen(self.img_game_over, wx.adv.SPLASH_CENTRE_ON_SCREEN | wx.adv.SPLASH_TIMEOUT,
                             4000, None, -1, wx.DefaultPosition, wx.DefaultSize,
                             wx.BORDER_SIMPLE | wx.STAY_ON_TOP)
                wx.Yield()
            else:
                self.etq_estado.Label = f"Turno: {self.juego.turno}"                
                self.tpo_act = VentPpal.TPO_JUG
                self.etq_tiempo.Label = f"{self.tpo_act}"
                self.timer.Start(VentPpal.TIMER_INTERVAL)

    def on_kill(self, fil, col):
        dc = wx.ClientDC(self.tablero)
        dc.Brush = wx.RED_BRUSH
        x, y = col*self.IMG_LX, fil*self.IMG_LY
        dc.DrawRectangle(x, y, self.IMG_LX, self.IMG_LY)
        elem = self.juego[fil, col]
        dc.DrawBitmap(self.imagen(elem), x, y)
        self.snd_kill.Play(wx.adv.SOUND_SYNC)
        time.sleep(0.3)

    def on_bebes(self, bebes):
        dc = wx.ClientDC(self.tablero)
        dc.Brush = wx.CYAN_BRUSH
        for pos in bebes:
            fil, col = pos[0], pos[1]
            x, y = col*self.IMG_LX, fil*self.IMG_LY
            dc.DrawRectangle(x, y, self.IMG_LX, self.IMG_LY)
            elem = self.juego[fil, col]
            dc.DrawBitmap(self.imagen(elem), x, y)
        self.snd_bebes.Play(wx.adv.SOUND_SYNC)
        time.sleep(0.3)

    def on_colapso(self, fil, col, grupo):
        dc = wx.ClientDC(self.tablero)
        dc.Brush = wx.YELLOW_BRUSH
        xd, yd = col*self.IMG_LX, fil*self.IMG_LY
        self.snd_colapso.Play()
        for i in range(11):
            for pos in grupo:
                x0, y0 = pos[1]*self.IMG_LX, pos[0]*self.IMG_LY
                dc.DrawRectangle(x0, y0, self.IMG_LX, self.IMG_LY)                
            for pos in grupo:
                elem = self.juego[pos[0], pos[1]]
                x0, y0 = pos[1]*self.IMG_LX, pos[0]*self.IMG_LY
                x = int(x0 + 0.1*i*(xd-x0))
                y = int(y0 + 0.1*i*(yd-y0))
                dc.DrawBitmap(self.imagen(elem), x, y)
            time.sleep(0.05)

    def on_movimiento(self, lis_mov):        
        dc = wx.ClientDC(self.tablero)
        dc.Brush = wx.WHITE_BRUSH        
        self.snd_movs.Play()
        for i in range(11):
            # Borramos las casillas
            for mov in lis_mov:
                x0, y0 = mov[1]*self.IMG_LX, mov[0]*self.IMG_LY
                x1, y1 = mov[3]*self.IMG_LX, mov[2]*self.IMG_LY
                dc.DrawRectangle(x0, y0, self.IMG_LX, self.IMG_LY)
                dc.DrawRectangle(x1, y1, self.IMG_LX, self.IMG_LY)
            # Dibujamos los bigfoots
            for mov in lis_mov:
                x0, y0 = mov[1]*self.IMG_LX, mov[0]*self.IMG_LY
                x1, y1 = mov[3]*self.IMG_LX, mov[2]*self.IMG_LY
                x = int(x0 + 0.1*i*(x1-x0))
                y = int(y0 + 0.1*i*(y1-y0))
                elem = self.juego[mov[2], mov[3]]
                dc.DrawBitmap(self.imagen(elem), x, y)
            time.sleep(0.05)

